CREATE OR REPLACE FUNCTION public.handle_message_notifications() RETURNS TRIGGER SECURITY DEFINER SET search_path = public AS  DECLARE v_other_user UUID; v_is_group BOOLEAN; BEGIN SELECT is_group INTO v_is_group FROM public.conversations WHERE id = NEW.conversation_id; IF NOT v_is_group THEN SELECT user_id INTO v_other_user FROM public.conversation_members WHERE conversation_id = NEW.conversation_id AND user_id != NEW.sender_id LIMIT 1; IF v_other_user IS NOT NULL THEN INSERT INTO public.notifications (user_id, type, payload) VALUES (v_other_user, 'DM_RECEIVED', jsonb_build_object('conversation_id', NEW.conversation_id, 'sender_id', NEW.sender_id, 'message_id', NEW.id)); END IF; END IF; RETURN NEW; END;  LANGUAGE plpgsql; 
